-- Athena saved query (Product_B2C_Intl)
-- ID: 02a809fd-5de2-4d5b-b938-365033c97373
-- Name: RTC Funnel Rollup - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH -- short_routes AS ( -- SELECT DISTINCT src_id, dest_id -- FROM lis.short_route_sds -- WHERE cohort = '2026' -- ), -- Deduped Funnel Steps (1 row per session + route) srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, CASE WHEN s.group_id > 0 THEN 'Banner Expand' ELSE 'Auto Expand' END AS expand_type, op_id, -- CASE WHEN sr.src_id IS NOT NULL THEN 'Short Routes' ELSE 'Long Routes' END AS route_type, CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi FROM "user_interaction"."search_route_details" s JOIN lis.bo_mappings bo ON bo.vendor_id = s.op_id AND bo.is_rtc = 'RTC' -- LEFT JOIN short_routes sr ON s.src_id = sr.src_id AND s.dest_id = sr.dest_id WHERE s.__time >= TIMESTAMP '2026-07-13 18:30:00' AND s.__time < TIMESTAMP '2026-07-27 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND op_id IN (10283, 16081, 6392, 15447, 8065, 15129, 7115, 10244, 10823, 15130, 11060, 15499, 11044, 3030, 15443, 16124, 16227, 2020, 16374, 16426, 16580, 16647, 16777, 17012, 16884, 4040, 17137, 17101, 17889, 18115, 18101, 18237, 18491, 19393, 19502, 22837, 22875, 22878, 24978, 25187, 25946, 27000, 26936, 27455, 28011, 29176, 29479, 29391, 29392, 32000, 32272, 32245, 34300, 34400, 33740, 35303, 35268, 33000) -- AND op_id IN (33000) -- AND s.os = 'Android' AND s.country = 'IND' AND s.status = 200 AND tp_channel = 'INVALID' AND akamai_bot IS NULL -- GROUP BY 1,2,3,4,5,6,7,8,9 ), sl_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-07-13 18:30:00' AND __time < TIMESTAMP '2026-07-27 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-07-13 18:30:00' AND __time < TIMESTAMP '2026-07-27 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), tco_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."create_order_details" WHERE __time >= TIMESTAMP '2026-07-13 18:30:00' AND __time < TIMESTAMP '2026-07-27 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-07-13 18:30:00' AND __time < TIMESTAMP '2026-07-27 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), -- addpay_deduped AS ( -- SELECT mri_session_id, MAX(rb_user_id) as rb_user_id -- FROM "user_interaction"."make_payment_details" -- WHERE __time >= TIMESTAMP '2026-07-13 18:30:00' AND __time < TIMESTAMP '2026-07-27 18:30:00' -- -- AND os = 'Android' -- AND country = 'IND' -- GROUP BY 1 -- ), confirm_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-07-13 18:30:00' AND __time < TIMESTAMP '2026-07-27 18:30:00' -- AND os = 'Android' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT -- 'MTD Dec 28' AS month_period, srp.doi, UPPER(srp.user_type) as user_type, srp.op_id bo_id, bo.travels bo_name, srp.expand_type, -- srp.route_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS CustInfoSession, COUNT(DISTINCT tco.mri_session_id) AS tcoload, COUNT(DISTINCT oi.mri_session_id) AS PaymentLandSessions, -- COUNT(DISTINCT ap.mri_session_id) AS AddPayClickSessions, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, -- COUNT(DISTINCT srp.rb_user_id) AS srpUsers, -- COUNT(DISTINCT sl.rb_user_id) AS slUsers, -- COUNT(DISTINCT pax.rb_user_id) AS paxUsers, -- COUNT(DISTINCT tco.rb_user_id) AS tcoUsers, -- COUNT(DISTINCT oi.rb_user_id) AS orderinfoUsers, -- COUNT(DISTINCT conf.rb_user_id) AS confirmUsers, SUM(conf.tin_count) AS tin FROM srp_deduped srp LEFT JOIN "lis"."operators" bo ON srp.op_id = bo.operator_id LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN tco_deduped tco ON srp.mri_session_id = tco.mri_session_id AND srp.route_id = tco.route_id LEFT JOIN orderinfo_deduped oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id -- LEFT JOIN addpay_deduped ap ON ap.mri_session_id = oi.mri_session_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1,2,3,4,5,6 ORDER BY 1, 6, 2 DESC
